using System.Text.Json;
using Microsoft.AspNetCore.Mvc;
using OnlineStore.Data;
using OnlineStore.Models;
namespace OnlineStore.Controllers;
public class OrdersController(StoreContext db) : Controller { const string CartKey="cart"; List<CartItem> Cart()=>JsonSerializer.Deserialize<List<CartItem>>(HttpContext.Session.GetString(CartKey)??"[]")??[]; public IActionResult Checkout() { var cart=Cart(); if(!cart.Any()) { TempData["Message"]="Your cart is empty."; return RedirectToAction("Index","Cart"); } ViewBag.Total=cart.Sum(x=>x.Subtotal); return View(new Order()); } [HttpPost] public async Task<IActionResult> Checkout(Order order) { var cart=Cart(); if(!cart.Any()) ModelState.AddModelError("", "Your cart is empty."); if(!ModelState.IsValid) { ViewBag.Total=cart.Sum(x=>x.Subtotal); return View(order); } order.OrderDate=DateTime.Now; order.Status="Pending"; order.TotalPrice=cart.Sum(x=>x.Subtotal); foreach(var item in cart) { var product=await db.Products.FindAsync(item.ProductId); if(product is null || product.StockQuantity < item.Quantity) { ModelState.AddModelError("", $"{item.Name} is no longer available in this quantity."); ViewBag.Total=order.TotalPrice; return View(order); } product.StockQuantity-=item.Quantity; order.OrderItems.Add(new OrderItem { ProductId=item.ProductId, Quantity=item.Quantity, UnitPrice=item.Price }); } db.Orders.Add(order); await db.SaveChangesAsync(); HttpContext.Session.Remove(CartKey); return RedirectToAction(nameof(Confirmation),new { id=order.Id }); } public async Task<IActionResult> Confirmation(int id) { var order=await db.Orders.FindAsync(id); return order is null ? NotFound() : View(order); } }
